import "server-only";

import { authors } from "@/lib/api";
import { must } from "@/lib/backend";
import type { Author, Book } from "@/lib/types";

export type AuthorCardProps = {
    author: Pick<Author, "id" | "name" | "born">;
};

export async function readAuthorCard(author: Author): Promise<AuthorCardProps> {
    return {
        author: {
            id: author.id,
            name: author.name,
            born: author.born,
        },
    };
}

export type AuthorViewProps = {
    author: Pick<Author, "id" | "name" | "born"> & {
        books: Pick<Book, "id" | "title">[];
    };
};

export async function readAuthorView(author: Author): Promise<AuthorViewProps> {
    const [books] = await Promise.all([
        must(authors.books(author.id)),
    ]);
    return {
        author: {
            id: author.id,
            name: author.name,
            born: author.born,
            books: books.map((item) => ({ id: item.id, title: item.title })),
        },
    };
}

export type BookShelfProps = {
    books: Array<Pick<Book, "id" | "title" | "genre" | "published" | "in_print"> & {
        author: Pick<Author, "id" | "name"> & { href: string };
    }>;
};

export async function readBookShelf(books: Book[]): Promise<BookShelfProps> {
    return {
        books: await Promise.all(
            books.map(async (record) => {
                const [author] = await Promise.all([
                    must(authors.get(record.author_id)),
                ]);
                return {
                    id: record.id,
                    title: record.title,
                    genre: record.genre,
                    published: record.published,
                    in_print: record.in_print,
                    author: { id: author.id, name: author.name, href: `/authors/${encodeURIComponent(author.id)}` },
                };
            }),
        ),
    };
}
